def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    positions = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                positions.setdefault(grid[r][c], []).append((r, c))

    # Color 1: two steps right, then one step up at the end.
    for r, c in positions.get(1, []):
        for j in (1, 2):
            if 0 <= r < h and 0 <= c + j < w:
                out[r][c + j] = 5
        if 0 <= r - 1 < h and 0 <= c + 2 < w:
            out[r - 1][c + 2] = 1

    # Color 2: a fixed-length horizontal ray to the left.
    for r, c in positions.get(2, []):
        for j in range(1, 5):
            if 0 <= r < h and 0 <= c - j < w:
                out[r][c - j] = 5 if j < 4 else 2

    # Color 3: three steps down; color 6: six steps up.
    vertical_paths = []
    for r, c in positions.get(3, []):
        path = [(r + j, c) for j in range(4)]
        vertical_paths.append(path)
        for j in range(1, 4):
            if r + j < h:
                out[r + j][c] = 5 if j < 3 else 3

    for r, c in positions.get(6, []):
        path = [(r - j, c) for j in range(7)]
        vertical_paths.append(path)
        for j in range(1, 7):
            if r - j >= 0:
                out[r - j][c] = 5 if j < 6 else 6

    # Crossings of the color-2 horizontal path with a vertical path
    # become 4 and continue diagonally down-left.
    for r, c in positions.get(2, []):
        horizontal = {(r, c - j) for j in range(5) if 0 <= c - j < w}
        for path in vertical_paths:
            for rr, cc in path:
                if (rr, cc) in horizontal and 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 4
                    k = 1
                    while rr + k < h and cc - k >= 0:
                        out[rr + k][cc - k] = 4
                        k += 1

    return out
